const p = (text) => `<p>${text}</p>`;
const section = (title, ...paragraphs) => `<section><h2>${title}</h2>${paragraphs.map(p).join("")}</section>`;
const table = (heads, rows) => `<div class="comparison-scroll"><table><thead><tr>${heads.map(x => `<th scope="col">${x}</th>`).join("")}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(x => `<td>${x}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
const list = (items) => `<ul>${items.map(x => `<li>${x}</li>`).join("")}</ul>`;
const source = (url, label) => `<p class="disclosure">확인 자료: <a href="${url}" target="_blank" rel="noopener">${label}</a>. 운영·판매 조건은 변경될 수 있습니다.</p>`;

